import{_ as n,C as d,o as r,c as l,ai as i,j as t,a,G as o}from"./chunks/framework.Ci0kozOl.js";const T=JSON.parse('{"title":"UnoPim Frontend Overview","description":"","frontmatter":{},"headers":[],"relativePath":"3.0/architecture/frontend.md","filePath":"3.0/architecture/frontend.md","lastUpdated":1786019473000}'),c={name:"3.0/architecture/frontend.md"},p={id:"ajax-navigation",tabindex:"-1"},h={id:"form-submission-and-flash-messages",tabindex:"-1"},u={id:"unsaved-changes-tracking",tabindex:"-1"},g={id:"dark-theme",tabindex:"-1"};function m(f,e,v,k,b,w){const s=d("Badge");return r(),l("div",null,[e[12]||(e[12]=i('<h1 id="unopim-frontend-overview" tabindex="-1">UnoPim Frontend Overview <a class="header-anchor" href="#unopim-frontend-overview" aria-label="Permalink to &quot;UnoPim Frontend Overview&quot;">​</a></h1><p>UnoPim&#39;s frontend uses modern tools and frameworks to create a responsive and dynamic user interface.</p><h2 id="tailwind-css" tabindex="-1">Tailwind CSS <a class="header-anchor" href="#tailwind-css" aria-label="Permalink to &quot;Tailwind CSS&quot;">​</a></h2><p>UnoPim uses <a href="https://tailwindcss.com/" target="_blank" rel="noreferrer">Tailwind CSS</a>, a customizable utility-first CSS framework for building responsive designs quickly.</p><ul><li><strong>Customization</strong>: Tailwind CSS offers flexible configuration to suit different project needs.</li><li><strong>Utility-First Approach</strong>: It provides utility classes for efficient design within HTML.</li></ul><p>To set up Tailwind CSS, define your Blade file path and the JavaScript directory in the <code>tailwind.config.js</code> file. Tailwind will compile the CSS from the defined location.</p><h2 id="vue-js" tabindex="-1">Vue.js <a class="header-anchor" href="#vue-js" aria-label="Permalink to &quot;Vue.js&quot;">​</a></h2><p>UnoPim’s dynamic UI is powered by <a href="https://vuejs.org/" target="_blank" rel="noreferrer">Vue.js</a>, a flexible JavaScript framework.</p><ul><li><strong>Reactive Components</strong>: Vue.js allows for real-time updates as data changes.</li><li><strong>Component-Based Architecture</strong>: Vue.js promotes reusable and maintainable components.</li></ul><p>UnoPim uses <a href="https://vitejs.dev/" target="_blank" rel="noreferrer">Vite</a> as a build tool, offering a faster development experience. The <code>vite.config.js</code> file defines the build paths, and Vite compiles CSS and JavaScript into the public directory.</p><h2 id="blade" tabindex="-1">Blade <a class="header-anchor" href="#blade" aria-label="Permalink to &quot;Blade&quot;">​</a></h2><p>UnoPim leverages the Blade template engine, integrated with <a href="https://laravel.com" target="_blank" rel="noreferrer">Laravel</a>, for creating flexible and dynamic templates.</p><ul><li><strong>Template Inheritance</strong>: Blade allows a modular structure through template inheritance.</li><li><strong>Directives</strong>: Blade simplifies common tasks like loops and conditionals with its built-in directives.</li></ul><p>For more details on UnoPim&#39;s directory structure and configuration, visit the <a href="https://devdocs.unopim.com/master/packages/views.html#directory-structure" target="_blank" rel="noreferrer">official documentation</a>.</p>',14)),t("h2",p,[e[0]||(e[0]=a("AJAX Navigation ",-1)),o(s,{type:"tip",text:"3.0"}),e[1]||(e[1]=a()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#ajax-navigation","aria-label":'Permalink to "AJAX Navigation <Badge type="tip" text="3.0" />"'},"​",-1))]),e[13]||(e[13]=i('<p>The admin navigates like a single-page app: link clicks inside the admin are intercepted, the destination is fetched with an <code>X-Ajax-Nav: true</code> header, and the <code>#app</code> subtree is swapped and remounted — browser history included (<code>pushState</code>/<code>popstate</code>).</p><p>Key facts for extension authors (<code>assets/js/plugins/navigation.js</code>; contract constants in <code>assets/js/constants.js</code>):</p><ul><li><strong>Opt out per link</strong> with the <code>data-no-ajax-nav</code> attribute (downloads, cross-origin, and <code>target</code> links are skipped automatically).</li><li><strong>Lifecycle events</strong> on <code>document</code>: <code>unopim:navigate:before</code> (cancelable), <code>unopim:navigate:success</code>, <code>unopim:navigate:error</code>. Any failure falls back to a full page load.</li><li><strong>Navigation guards</strong>: <code>window.unopim.registerNavigationGuard(fn)</code> — return <code>false</code> (sync or async) to cancel a visit. The unsaved-changes bar uses this to prompt before leaving.</li><li><strong>Programmatic visits</strong>: <code>window.unopim.visit(url)</code>, or <code>this.$navigate(url)</code> inside Vue components.</li><li>Inline page scripts and Vue <code>x-template</code> scripts are re-executed per visit with template ids remapped, so <strong>page-scoped scripts must be idempotent</strong>.</li></ul><div class="warning custom-block"><p class="custom-block-title">For browser tests</p><p>Clicking an admin link is an AJAX visit, not a full page load. E2E tests that wait for navigation events must wait for the DOM swap instead.</p></div>',4)),t("h2",h,[e[3]||(e[3]=a("Form Submission and Flash Messages ",-1)),o(s,{type:"tip",text:"3.0"}),e[4]||(e[4]=a()),e[5]||(e[5]=t("a",{class:"header-anchor",href:"#form-submission-and-flash-messages","aria-label":'Permalink to "Form Submission and Flash Messages <Badge type="tip" text="3.0" />"'},"​",-1))]),e[14]||(e[14]=i('<p>Forms rendered with <code>&lt;x-admin::form ajax&gt;</code> post their raw <code>FormData</code> with an <code>X-Ajax-Form: true</code> header. Server-side, the <code>ConvertAjaxFormRedirect</code> middleware converts controller redirects into JSON. On success the app emits the <code>add-flash</code> and <code>form-saved</code> mitt events and navigates to <code>redirect_url</code>; on 422 it maps errors onto fields and reveals the first invalid one. Any component can raise a toast:</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">this</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.$emitter.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">emit</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;add-flash&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, { type: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;success&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, message: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;...&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> });</span></span></code></pre></div>',2)),t("h2",u,[e[6]||(e[6]=a("Unsaved-Changes Tracking ",-1)),o(s,{type:"tip",text:"3.0"}),e[7]||(e[7]=a()),e[8]||(e[8]=t("a",{class:"header-anchor",href:"#unsaved-changes-tracking","aria-label":'Permalink to "Unsaved-Changes Tracking <Badge type="tip" text="3.0" />"'},"​",-1))]),e[15]||(e[15]=i('<p>Edit forms sit inside <code>&lt;x-admin::form.unsaved-changes&gt;</code>: the component snapshots the form&#39;s <code>FormData</code>, watches for real user input, and shows a global Save/Discard bar when values differ. Integration points for custom widgets:</p><table tabindex="0"><thead><tr><th>Hook</th><th>Use</th></tr></thead><tbody><tr><td><code>unsaved-changes:touch</code> (bubbling DOM event, <code>detail: {name}</code>)</td><td>Tell the bar a field changed when plain input events can&#39;t see it (WYSIWYG, uploaders, drawers)</td></tr><tr><td><code>unsaved-changes:sync</code> (bubbling DOM event)</td><td>Re-baseline dynamically added fields</td></tr><tr><td><code>$emitter.on(&#39;unsaved-changes:reset&#39;, fn)</code></td><td>Restore your internal state when the admin discards</td></tr><tr><td><code>data-unsaved-ignore</code> / <code>data-unsaved-managed</code></td><td>Exclude a subtree from tracking / from discard-revert</td></tr><tr><td><code>[data-control-group]</code> / <code>[data-dirty-section]</code></td><td>Field grouping for dirty badges and the section counter</td></tr></tbody></table><p>The bar registers itself as a navigation guard, so AJAX navigation, <code>beforeunload</code>, and the discard confirmation all behave consistently.</p>',3)),t("h2",g,[e[9]||(e[9]=a("Dark Theme ",-1)),o(s,{type:"tip",text:"3.0"}),e[10]||(e[10]=a()),e[11]||(e[11]=t("a",{class:"header-anchor",href:"#dark-theme","aria-label":'Permalink to "Dark Theme <Badge type="tip" text="3.0" />"'},"​",-1))]),e[16]||(e[16]=i('<p>Theme state is a plain (unencrypted) <code>dark_mode</code> cookie with values <code>auto | light | dark</code>. Layouts read the cookie server-side and set <code>class=&quot;dark&quot;</code> on <code>&lt;html&gt;</code> before paint; an inline script resolves <code>auto</code> against <code>prefers-color-scheme</code>, so there is no flash. The header toggle emits the <code>change-theme</code> mitt event on every switch.</p><p>Styling rules: colors come from CSS tokens in <code>assets/css/app.css</code> (<code>--c-primary-50…900</code>, <code>--c-success/warning/danger/info</code>, <code>--chart-*</code>) declared as space-separated RGB channels so Tailwind opacity modifiers work. Dark surfaces use the <code>dark:bg-cherry-*</code> scale. <strong>Never hardcode a color</strong> — add a token and expose it through <code>tailwind.config.js</code>.</p><h2 id="package-views-and-the-tailwind-build" tabindex="-1">Package Views and the Tailwind Build <a class="header-anchor" href="#package-views-and-the-tailwind-build" aria-label="Permalink to &quot;Package Views and the Tailwind Build&quot;">​</a></h2><p>The Admin theme&#39;s <code>tailwind.config.js</code> scans sibling packages (<code>&quot;../*/src/Resources/**/*.blade.php&quot;</code>, <code>&quot;../*/src/Resources/**/*.js&quot;</code>), so utilities used only in your package&#39;s views are still generated. Build the theme from <code>packages/Webkul/Admin</code> — the root Vite build covers only the app shell. TinyMCE and fonts are self-hosted by the build (no runtime CDN access needed).</p>',4))])}const _=n(c,[["render",m]]);export{T as __pageData,_ as default};
